// Port of ShellCheck src/ShellCheck/Analytics.hs, Checks/Commands.hs and Checks/ShellSupport.hs (e11f964)
//
// One file per check: `src/<module>/<snake_name>.rs`, each registering a
// `CheckEntry` in `shellcheck_analyzer::api::CHECKS`. The `mod` lines for the
// module directories are generated by `build.rs`. See docs/porting-a-check.md.
#![forbid(unsafe_code)]

pub mod support;

/// Checks of ShellCheck src/ShellCheck/Analytics.hs
pub mod analytics {
    include!(concat!(env!("OUT_DIR"), "/analytics.rs"));
}

/// Checks of ShellCheck src/ShellCheck/Checks/Commands.hs
pub mod commands {
    include!(concat!(env!("OUT_DIR"), "/commands.rs"));
}

/// Checks of ShellCheck src/ShellCheck/Checks/ShellSupport.hs
pub mod shell_support {
    include!(concat!(env!("OUT_DIR"), "/shell_support.rs"));
}
